        INSERT INTO sp_bimobjvo("objId", "referencedId", category, family, type, "elementId", "definitionObjIdList", "definitionElementIdList")
SELECT #{objId}, #{referencedId}, #{category}, #{family}, #{type}, #{elementId}, '{}', '{}'
WHERE NOT EXISTS (
    SELECT 1
    FROM sp_bimobjvo
    WHERE "objId" = #{objId}
);
